class Solution {
    public boolean carPooling(int[][] trips, int capacity) {
        int end = 0;
        for (int[] t : trips) end = Math.max(end, t[2]);
        for (int x = 0; x < end; x++) {
            int load = 0;
            for (int[] t : trips) if (t[1] <= x && x < t[2]) load += t[0];
            if (load > capacity) return false;
        }
        return true;
    }
}

