    public int reversePairs(int[] nums) {
        List<Integer> sorted = new ArrayList<>();
        int count = 0;
        for (int x : nums) {
            long limit = 2L * x;
            int lo = 0, hi = sorted.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (sorted.get(mid) <= limit) lo = mid + 1;
                else hi = mid;
